class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

function count(text, field, least) {
  if (!COUNT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function parse(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    try {
      const d = t[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (events.length) throw new Fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (t.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        const capacity = count(t[2], 'capacity', 1)
        const refill = count(t[3], 'refill', 0)
        const per = count(t[4], 'per', 1)
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per })
      } else if (d === 'window') {
        if (t.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        const limit = count(t[2], 'limit', 0)
        const span = count(t[3], 'span', 1)
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { kind: 'window', name: t[1], limit, span })
      } else if (d === 'route') {
        if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
        const list = []
        for (const p of t.slice(2)) {
          if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
          list.push(policies.get(p))
        }
        routes.set(t[1], list)
      } else if (d === 'event') {
        if (t.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = count(t[1], 'tick', 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: t[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) {
        process.stderr.write(`error: line ${i + 1}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
  }
  return { routes, events }
}

const { routes, events } = parse(readFileSync(0, 'utf8'))

const states = new Map()
function stateFor(p, key) {
  const id = p.name + '\0' + key
  return states.get(id)
}

function advance(p, key, tick) {
  const id = p.name + '\0' + key
  let s = states.get(id)
  if (p.kind === 'bucket') {
    // tokens scaled by `per` so fractions stay exact
    if (!s) {
      s = { scaled: p.capacity * p.per, last: tick }
      states.set(id, s)
    } else {
      s.scaled += p.refill * (tick - s.last)
      const cap = p.capacity * p.per
      if (s.scaled > cap) s.scaled = cap
      s.last = tick
    }
  } else {
    if (!s) {
      s = { ticks: [] }
      states.set(id, s)
    }
    const cutoff = tick - p.span
    s.ticks = s.ticks.filter((x) => x > cutoff)
  }
}

function allows(p, key) {
  const s = stateFor(p, key)
  return p.kind === 'bucket' ? s.scaled >= p.per : BigInt(s.ticks.length) < p.limit
}

function record(p, key, tick) {
  const s = stateFor(p, key)
  if (p.kind === 'bucket') s.scaled -= p.per
  else s.ticks.push(tick)
}

const out = []
const per = new Map()
let totalA = 0
let totalD = 0
for (const { tick, key } of events) {
  let best = null
  for (const prefix of routes.keys()) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
  }
  let denier = null
  if (best !== null) {
    const list = routes.get(best)
    for (const p of list) advance(p, key, tick)
    for (const p of list) {
      if (!allows(p, key)) { denier = p; break }
    }
    if (!denier) for (const p of list) record(p, key, tick)
  }
  const c = per.get(key) || { a: 0, d: 0 }
  per.set(key, c)
  if (denier) { c.d++; totalD++; out.push(`${tick} ${key} deny ${denier.name}`) }
  else { c.a++; totalA++; out.push(`${tick} ${key} allow`) }
}

if (mode === 'summary') {
  const o = []
  for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    o.push(`${k} allowed=${per.get(k).a} denied=${per.get(k).d}`)
  }
  o.push(`total allowed=${totalA} denied=${totalD}`)
  process.stdout.write(o.join('\n') + '\n')
} else if (out.length) {
  process.stdout.write(out.join('\n') + '\n')
}
